INSERT INTO creature_questrelation (id, quest) SELECT id - 990500 + 990900, quest FROM gameobject_questrelation WHERE id BETWEEN 990500 AND 990599;
INSERT INTO creature_involvedrelation (id, quest) SELECT id - 990500 + 990900, quest FROM gameobject_involvedrelation WHERE id BETWEEN 990500 AND 990599;
INSERT INTO creature (guid, id, map, spawnMask, position_x, position_y, position_z, orientation, spawntimesecsmin, spawntimesecsmax, spawndist, MovementType) SELECT guid - 9905000 + 9910000, id - 990500 + 990900, map, 1, position_x, position_y, position_z + 2.2, orientation, 30, 30, 0, 0 FROM gameobject WHERE id BETWEEN 990500 AND 990599;
